package com.aetheris.workflow.service;

import com.aetheris.security.protocol.execution.WorkflowQualityParent;
import com.aetheris.workflow.entity.TaskInstance;
import com.aetheris.workflow.fixedexecution.*;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.BeanPropertyRowMapper;
import java.time.OffsetDateTime;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Real PG parent/pipeline/fence constraints; child definitions/results/receipts are controlled fixtures. */
class WorkflowQualityAuthorityPostgresIT extends PipelineSqlAuthorityPostgresIT {
    long quality(){long id=jdbc.queryForObject("INSERT INTO workflow.task(name,task_type,quality_rule_id,timeout_seconds) VALUES(?,'quality',501,30) RETURNING id",Long.class,"quality-parent-"+UUID.randomUUID());sql.approveQuality(sql.definition(id),WorkflowActor.manual(user(43,4)),2,"a".repeat(64));return id;}
    WorkflowQualityParent parent(WorkflowExecutionStore.Claim claim){var e=claim.execution();var ref=new WorkflowQualityParent.Reference(e.instance().getId(),e.attemptId(),e.fencingToken(),claim.revision(),claim.manifestSha256());var lookup=sql.qualityParent(ref);return WorkflowQualityParent.parse(lookup.canonicalManifest(),lookup.manifestSha256(),ref);}
    WorkflowQualityFacade facade(){var instances=mock(TaskInstanceService.class);when(instances.getById(any())).thenAnswer(c->jdbc.queryForObject("SELECT * FROM workflow.task_instance WHERE id=?",new BeanPropertyRowMapper<>(TaskInstance.class),((Number)c.getArgument(0)).longValue()));return new WorkflowQualityFacade(sql,mock(WorkflowQualityClient.class),jdbc,manager,coordinator,instances);}
    WorkflowQualityClient.Result result(long id,String state){boolean terminal=Set.of("passed","failed","error").contains(state);return new WorkflowQualityClient.Result(id,501,"c".repeat(64),terminal?9001L:null,state,terminal&&!"error".equals(state)?"passed".equals(state)?0L:2L:null,0,terminal&&!"error".equals(state)?4L:null,terminal?OffsetDateTime.now().toString():null);}
    TaskInstance instance(WorkflowExecutionStore.Claim claim){return jdbc.queryForObject("SELECT * FROM workflow.task_instance WHERE id=?",new BeanPropertyRowMapper<>(TaskInstance.class),claim.execution().instance().getId());}
    @Test void manualQualityPinsRuleRevisionHashAndOriginalActorWithoutAnSqlBridge(){long id=quality();var claim=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));var p=parent(claim);assertEquals(501,p.qualityRuleId());assertEquals(2,p.qualityExecutionRevision());assertEquals("a".repeat(64),p.qualityDefinitionSha256());assertEquals("manual",p.actor().get("kind").asText());assertEquals(42,p.childActor().get("uid").asLong());assertEquals(3,p.childActor().get("accessVersion").asLong());assertThrows(IllegalStateException.class,()->sql.lookup(p.reference().instanceId(),p.reference().attemptId(),p.reference().fence()));assertEquals(1,attempts(id));}
    @Test void qualityCronUsesBoundGenerationAndChangingItInvalidatesTheOldSource(){long id=quality();jdbc.update("UPDATE workflow.task SET cron_expression='0 0 1 * * ?' WHERE id=?",id);var d=sql.definition(id);sql.bindCron(id,d.revision(),d.scheduleGeneration(),WorkflowActor.manual(user(42,3)));d=sql.definition(id);var claim=sql.claimScheduled(id,date,d.scheduleGeneration());var p=parent(claim);assertEquals("cron",p.actor().get("kind").asText());jdbc.update("UPDATE workflow.task SET cron_expression='0 1 1 * * ?' WHERE id=?",id);assertThrows(IllegalStateException.class,()->sql.qualityParent(p.reference()));assertThrows(IllegalStateException.class,()->sql.claimScheduled(id,"2026-10-26",p.reference().executionRevision()));assertEquals(1,attempts(id));}
    @Test void changingPinnedRuleOrParentDefinitionRequiresNewApproval(){long id=quality();var approved=sql.definition(id);var claim=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));var p=parent(claim);jdbc.update("UPDATE workflow.task SET quality_execution_revision=3 WHERE id=?",id);assertFalse(sql.definition(id).approved());assertThrows(IllegalStateException.class,()->sql.qualityParent(p.reference()));assertThrows(IllegalStateException.class,()->sql.approveQuality(approved,WorkflowActor.manual(user(43,4)),3,"b".repeat(64)));assertEquals(1,attempts(id));}
    @Test void exactOriginalChildReceiptClosesUnknownAndCannotBeReplaced(){long id=quality();var claim=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));var p=parent(claim);var f=facade();f.accept(p,result(5001,"running"));coordinator.submissionUnknown(claim.execution(),"controlled lost submit response");f.accept(p,result(5001,"passed"));assertEquals("success",instance(claim).getStatus());assertEquals(5001,jdbc.queryForObject("SELECT quality_result_id FROM workflow.execution_attempt WHERE id=?",Long.class,p.reference().attemptId()));assertEquals(9001,jdbc.queryForObject("SELECT metadata_receipt_id FROM workflow.execution_attempt WHERE id=?",Long.class,p.reference().attemptId()));assertThrows(IllegalStateException.class,()->f.accept(p,result(5002,"passed")));assertThrows(DataAccessException.class,()->jdbc.update("UPDATE workflow.execution_attempt SET quality_manifest_sha256=? WHERE id=?","d".repeat(64),p.reference().attemptId()));assertThrows(DataAccessException.class,()->jdbc.update("UPDATE workflow.execution_attempt SET quality_evidence_json='{}',quality_evidence_sha256=encode(sha256('{}'::bytea),'hex') WHERE id=?",p.reference().attemptId()));}
    @Test void lateOldChildCannotCompleteANewAttempt(){long id=quality();var old=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));var p=parent(old);facade().accept(p,result(5001,"failed"));var current=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));assertThrows(IllegalStateException.class,()->facade().accept(p,result(5001,"passed")));assertEquals("running",instance(current).getStatus());assertEquals(2,attempts(id));}
    @Test void concurrentReceiptReconciliationCompletesOnlyOneOriginalAttempt() throws Exception {long id=quality();var claim=sql.claimManual(id,date,WorkflowActor.manual(user(42,3)));var p=parent(claim);coordinator.submissionUnknown(claim.execution(),"controlled restart");var f=facade();try(var workers=Executors.newFixedThreadPool(2)){var a=workers.submit(()->f.accept(p,result(5001,"passed")));var b=workers.submit(()->f.accept(p,result(5001,"passed")));a.get(5,TimeUnit.SECONDS);b.get(5,TimeUnit.SECONDS);}assertEquals("success",instance(claim).getStatus());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM workflow.execution_event WHERE attempt_id=? AND event_type='quality_child_reconciled'",Integer.class,p.reference().attemptId()));}
    @Test void qualityPipelineWaiverRequiresBoundFailedChildAndCannotWaiveUnknown(){long first=quality(),second=task();jdbc.update("INSERT INTO workflow.task_dependency(task_id,upstream_task_id) VALUES(?,?)",second,first);approve(second);var graph=new long[]{first,second};long run=create(graph);var dispatch=pipelines.begin(run);var claim=pipelines.prepare(dispatch,first);var p=parent(claim);assertEquals("pipeline",p.actor().get("kind").asText());long waiver=jdbc.queryForObject("INSERT INTO workflow.quality_waiver(quality_task_id,biz_date,reason,approved_by,expires_at) VALUES(?,?,'controlled confirmed-quality waiver','fixture-user-43',clock_timestamp()+interval '1 hour') RETURNING id",Long.class,first,date);assertFalse(pipelines.record(dispatch,first,claim,instance(claim),"waived",waiver));assertThrows(IllegalStateException.class,()->pipelines.prepare(dispatch,second));facade().accept(p,result(5001,"failed"));assertTrue(pipelines.record(dispatch,first,claim,instance(claim),"waived",waiver));var downstream=pipelines.prepare(dispatch,second);record(dispatch,second,downstream,complete(downstream,true));pipelines.finish(dispatch,"succeeded",null,null);assertEquals("succeeded",state(run));assertEquals("failed",instance(claim).getStatus());assertEquals(1,attempts(second));}
    @Test void failingFirstThirtyTwoParentReadbacksCannotStarveALaterOriginalReceipt(){
        var claims=new ArrayList<WorkflowExecutionStore.Claim>();WorkflowQualityParent last=null;
        for(int i=0;i<34;i++){var claim=sql.claimManual(quality(),date,WorkflowActor.manual(user(42,3)));last=parent(claim);claims.add(claim);coordinator.submissionUnknown(claim.execution(),"controlled lost child response");}
        var target=Objects.requireNonNull(last).reference();var client=mock(WorkflowQualityClient.class);
        when(client.status(any())).thenAnswer(c->{var ref=(WorkflowQualityParent.Reference)c.getArgument(0);if(ref.equals(target))return result(5001,"passed");throw new IllegalStateException("controlled unavailable old child");});
        var f=new WorkflowQualityFacade(sql,client,jdbc,manager,coordinator,mock(TaskInstanceService.class));
        for(int i=0;i<20&&!"success".equals(instance(claims.getLast()).getStatus());i++)f.reconcile();
        assertEquals("success",instance(claims.getLast()).getStatus());for(var old:claims.subList(0,33))assertEquals("unknown",instance(old).getStatus());verify(client,never()).submit(any());
    }
}
